message.content:
{
  "claims": [
    {
      "text": "Monitor respiratory status and oxygen saturation closely given tachypnea (RR up to 27) and SpO2 92-97% on 2-3 L/min nasal cannula.",
      "action_type": "monitored",
      "target": "respiratory status and oxygen saturation"
    },
    {
      "text": "Monitor heart rate and blood pressure, as tachycardia (HR 104-105) and blood pressure within alarm parameters (SBP 132-134) persist.",
      "action_type": "monitored",
      "target": "heart rate and blood pressure"
    },
    {
      "text": "Assess and manage pain, with current pain level mild to moderate (3-5), using available analgesics as needed.",
      "action_type": "assessment_performed",
      "target": "pain"
    },
    {
      "text": "Monitor temperature given low-grade fever (99.7°F) and leukocytosis (WBC 19 K/uL), and evaluate for infection.",
      "action_type": "monitored",
      "target": "temperature and infection status"
    },
    {
      "text": "Continue venous thromboembolism prophylaxis with subcutaneous heparin 5000 units as ordered.",
      "action_type": "therapy_continued",
      "target": "VTE prophylaxis"
    },
    {
      "text": "Maintain fall precautions and assist with mobility given weak gait/transferring and bed rest with IV/saline lock.",
      "action_type": "monitored",
      "target": "fall risk and mobility"
    },
    {
      "text": "Monitor electrolytes and renal function (sodium 138, potassium 3.6, creatinine 0.4, BUN 9) and recheck as clinically indicated.",
      "action_type": "monitored",
      "target": "electrolytes and renal function"
    },
    {
      "text": "Monitor hemoglobin/hematocrit (11.2 g/dL / 33.6%) for stability, with no evidence of active bleeding.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Continue cardiac monitoring with ST segment monitoring and alarms on.",
      "action_type": "monitored",
      "target": "cardiac rhythm"
    },
    {
      "text": "Perform daily sedation and delirium assessment (Richmond-RAS 0, CAM-ICU negative).",
      "action_type": "assessment_performed",
      "target": "sedation and delirium"
    }
  ]
}

{
  "claims": [
    {
      "text": "Recheck serum magnesium and replete if still low, targeting normalization given level of 1.5 mEq/L.",
      "action_type": "monitored",
      "target": "serum magnesium"
    },
    {
      "text": "Monitor WBC and differential given leukocytosis of 17-20.1 K/uL with neutrophilia; assess for infection source.",
      "action_type": "assessment_performed",
      "target": "infection evaluation"
    },
    {
      "text": "Monitor blood glucose and administer sliding-scale insulin as ordered for glucose 146-161 mg/dL.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Maintain continuous cardiac and SpO2 monitoring with alarms on; monitor for arrhythmia given magnesium 1.5 mEq/L.",
      "action_type": "monitored",
      "target": "cardiac telemetry and pulse oximetry"
    },
    {
      "text": "Monitor blood pressure closely given recent systolic 94/54 mmHg and antihypertensive diuretic therapy (metolazone, spironolactone).",
      "action_type": "monitored",
      "target": "blood pressure"
    },
    {
      "text": "Recheck basic metabolic panel including potassium and magnesium within 24 hours.",
      "action_type": "specimen_collected",
      "target": "basic metabolic panel"
    },
    {
      "text": "Assess and manage pain with scheduled/PRN analgesia, reassessing response given moderate pain scores.",
      "action_type": "assessment_performed",
      "target": "pain"
    },
    {
      "text": "Maintain bed rest with fall precautions and assist with mobility given Braden activity bedfast and IV access.",
      "action_type": "monitored",
      "target": "fall precautions"
    },
    {
      "text": "Continue supplemental oxygen at 2 L/min via nasal cannula to maintain SpO2 above 92%.",
      "action_type": "therapy_continued",
      "target": "supplemental oxygen"
    },
    {
      "text": "Continue bowel regimen with docusate and bisacodyl as ordered; monitor bowel function.",
      "action_type": "therapy_continued",
      "target": "bowel regimen"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain blood cultures and additional diagnostic specimens to evaluate suspected infection, given leukocytosis (WBC up to 27.9 K/uL) and ongoing antibiotics.",
      "action_type": "specimen_collected",
      "target": "blood cultures"
    },
    {
      "text": "Continue broad-spectrum antimicrobial therapy (levofloxacin, metronidazole, oral vancomycin) and reassess response.",
      "action_type": "therapy_continued",
      "target": "antimicrobial therapy"
    },
    {
      "text": "Monitor hemodynamics closely given hypotension (systolic 89–99 mmHg, MAP 62–67 mmHg) and tachycardia (HR 100–103 bpm).",
      "action_type": "monitored",
      "target": "hemodynamic status"
    },
    {
      "text": "Assess and manage pain with the currently available analgesic regimen, reassessing pain scores.",
      "action_type": "assessment_performed",
      "target": "pain"
    },
    {
      "text": "Monitor oxygen saturation and respiratory status on 4 L/min nasal cannula; titrate oxygen to maintain SpO2 above desaturation limit.",
      "action_type": "monitored",
      "target": "oxygenation and respiratory status"
    },
    {
      "text": "Monitor serum electrolytes and renal function, including sodium (128–133 mEq/L), bicarbonate (18–20 mEq/L), and creatinine (0.8–0.9 mg/dL).",
      "action_type": "monitored",
      "target": "electrolytes and renal function"
    },
    {
      "text": "Monitor hemoglobin/hematocrit (9.3–10.2 g/dL / 28.7–32.3%) and assess for bleeding or need for transfusion.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Implement fall precautions and maintain bed rest given high fall risk and bedfast status.",
      "action_type": "ordered",
      "target": "fall precautions"
    },
    {
      "text": "Perform oral care and dysphagia screening given mildly impaired swallow and oral cavity findings.",
      "action_type": "assessment_performed",
      "target": "swallowing and oral care"
    },
    {
      "text": "Monitor lactate trend (1.5–2.4 mmol/L) and perfusion status.",
      "action_type": "monitored",
      "target": "lactate and perfusion"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue phenylephrine infusion for hemodynamic support and monitor blood pressure closely.",
      "action_type": "therapy_continued",
      "target": "hemodynamic status"
    },
    {
      "text": "Monitor troponin and CK-MB trends to evaluate for acute myocardial injury.",
      "action_type": "monitored",
      "target": "cardiac biomarkers"
    },
    {
      "text": "Continue insulin therapy and monitor blood glucose frequently, treating hyperglycemia.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Monitor lactate levels and hemodynamic status for resolution of lactic acidosis.",
      "action_type": "monitored",
      "target": "lactate"
    },
    {
      "text": "Continue heparin infusion and monitor coagulation parameters.",
      "action_type": "therapy_continued",
      "target": "anticoagulation"
    },
    {
      "text": "Monitor renal function and urine output given elevated creatinine and uremia.",
      "action_type": "monitored",
      "target": "renal function"
    },
    {
      "text": "Monitor electrolytes, including sodium and magnesium, and replace as needed.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Monitor oxygen saturation and respiratory status, adjusting oxygen therapy as needed.",
      "action_type": "monitored",
      "target": "oxygenation"
    },
    {
      "text": "Perform chest pain assessment and obtain serial electrocardiograms.",
      "action_type": "assessment_performed",
      "target": "chest pain"
    },
    {
      "text": "Maintain bed rest and fall precautions given weakness and bedfast status.",
      "action_type": "monitored",
      "target": "mobility safety"
    }
  ]
}

{
  "claims": [
    {
      "text": "Transfuse packed red blood cells for hemoglobin 7.7 g/dL with hematocrit 27.6% in the ICU setting.",
      "action_type": "ordered",
      "target": "packed red blood cells"
    },
    {
      "text": "Monitor hemoglobin and hematocrit to assess response to transfusion and ongoing anemia.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Monitor for alcohol withdrawal using CIWA-Ar given history of ETOH use and tremor on exam.",
      "action_type": "monitored",
      "target": "alcohol withdrawal (CIWA-Ar)"
    },
    {
      "text": "Administer thiamine 100 mg IV for alcohol use disorder and nutritional risk.",
      "action_type": "administered",
      "target": "thiamine"
    },
    {
      "text": "Administer folic acid 1 mg PO/NG for alcohol use disorder and macrocytic anemia evaluation.",
      "action_type": "administered",
      "target": "folic acid"
    },
    {
      "text": "Monitor blood glucose given fingerstick glucose 208 and 294 mg/dL.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Monitor serum potassium given 3.4 mEq/L and ongoing D5NS infusion.",
      "action_type": "monitored",
      "target": "serum potassium"
    },
    {
      "text": "Monitor serum magnesium given 1.8 mg/dL.",
      "action_type": "monitored",
      "target": "serum magnesium"
    },
    {
      "text": "Monitor neurologic status including GCS, CAM-ICU, and RASS given fluctuating mental status.",
      "action_type": "monitored",
      "target": "neurologic status"
    },
    {
      "text": "Assess fall risk and implement fall precautions given history of falls and bed rest status.",
      "action_type": "assessment_performed",
      "target": "fall risk"
    }
  ]
}

{
  "claims": [
    {
      "text": "Obtain repeat arterial blood gas to reassess respiratory acidosis (pH 7.25-7.27, pCO2 54-55 mm Hg) and oxygenation on current oxygen support.",
      "action_type": "specimen_collected",
      "target": "arterial blood"
    },
    {
      "text": "Assess need for ventilatory support or escalation of respiratory support given persistent hypercapnic acidosis and tachypnea/dyspnea on high-flow oxygen.",
      "action_type": "assessment_performed",
      "target": "respiratory status"
    },
    {
      "text": "Monitor hemodynamics closely with arterial line given hypotension (ABP mean 84-89 mm Hg) and tachycardia (heart rate 99-103 bpm).",
      "action_type": "monitored",
      "target": "hemodynamic status"
    },
    {
      "text": "Continue epidural analgesia infusion (bupivacaine 0.1% at 11 mL/hr) and monitor pain control and sensory/motor function.",
      "action_type": "therapy_continued",
      "target": "epidural analgesia"
    },
    {
      "text": "Continue PCA hydromorphone for pain management and monitor total dose, attempts, and sedation level.",
      "action_type": "therapy_continued",
      "target": "PCA hydromorphone"
    },
    {
      "text": "Recheck serum magnesium given prior hypomagnesemia (1.5 mg/dL) and ongoing magnesium supplementation.",
      "action_type": "specimen_collected",
      "target": "serum magnesium"
    },
    {
      "text": "Recheck basic metabolic panel to monitor electrolytes, renal function, and acid-base status.",
      "action_type": "specimen_collected",
      "target": "basic metabolic panel"
    },
    {
      "text": "Monitor blood glucose and continue insulin therapy as ordered for hyperglycemia (glucose 120-131 mg/dL).",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Continue incentive spirometry and cough/deep breathing exercises to prevent pulmonary complications.",
      "action_type": "therapy_continued",
      "target": "respiratory hygiene"
    },
    {
      "text": "Maintain venous thromboembolism prophylaxis with subcutaneous heparin as ordered.",
      "action_type": "ordered",
      "target": "VTE prophylaxis"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue invasive mechanical ventilation with lung-protective settings and monitor respiratory status closely.",
      "action_type": "therapy_continued",
      "target": "respiratory system"
    },
    {
      "text": "Continue vasopressor or hemodynamic support as needed and monitor arterial blood pressure closely.",
      "action_type": "monitored",
      "target": "hemodynamic status"
    },
    {
      "text": "Continue fentanyl and propofol infusions for sedation and analgesia, titrating to goal RASS -1.",
      "action_type": "therapy_continued",
      "target": "sedation and analgesia"
    },
    {
      "text": "Obtain repeat arterial blood gas to reassess acid-base status and lactate clearance.",
      "action_type": "specimen_collected",
      "target": "arterial blood"
    },
    {
      "text": "Monitor serum lactate trend to assess tissue perfusion and response to resuscitation.",
      "action_type": "monitored",
      "target": "lactate"
    },
    {
      "text": "Continue intravenous calcium gluconate and magnesium sulfate replacement for hypocalcemia and hypomagnesemia.",
      "action_type": "therapy_continued",
      "target": "electrolyte repletion"
    },
    {
      "text": "Administer sodium bicarbonate for severe metabolic acidosis if pH remains below 7.20, per clinical judgment.",
      "action_type": "ordered",
      "target": "metabolic acidosis"
    },
    {
      "text": "Monitor platelet count and coagulation parameters given thrombocytopenia and elevated INR/PTT.",
      "action_type": "monitored",
      "target": "coagulation status"
    },
    {
      "text": "Monitor liver function tests and bilirubin given cholestatic pattern and coagulopathy.",
      "action_type": "monitored",
      "target": "liver function"
    },
    {
      "text": "Perform daily sedation interruption and spontaneous breathing trial assessment when clinically appropriate.",
      "action_type": "assessment_performed",
      "target": "ventilator weaning readiness"
    }
  ]
}

{
  "claims": [
    {
      "text": "Initiate or continue continuous renal replacement therapy for severe acute kidney injury with creatinine 6.7-7.3 mg/dL, BUN 89-93 mg/dL, and metabolic acidosis.",
      "action_type": "therapy_continued",
      "target": "renal replacement therapy"
    },
    {
      "text": "Transfuse platelets for severe thrombocytopenia with platelet count 12-13 K/uL and active critical illness.",
      "action_type": "ordered",
      "target": "platelet transfusion"
    },
    {
      "text": "Continue mechanical ventilation with lung-protective settings and monitor oxygenation, given intubation, FiO2 70-80%, PEEP 8-10 cmH2O, and persistent hypoxemia.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue vasopressor support with norepinephrine infusion and monitor hemodynamics for shock with lactic acidosis (lactate 3-4.8 mmol/L).",
      "action_type": "therapy_continued",
      "target": "vasopressor therapy"
    },
    {
      "text": "Obtain repeat arterial blood gas to reassess severe metabolic acidosis (pH 7.22-7.24, bicarbonate 11-15 mEq/L, base excess -11 to -14 mEq/L).",
      "action_type": "specimen_collected",
      "target": "arterial blood gas"
    },
    {
      "text": "Replete potassium intravenously for hypokalemia with potassium 3.0 mEq/L.",
      "action_type": "ordered",
      "target": "potassium chloride"
    },
    {
      "text": "Replete magnesium intravenously for hypomagnesemia with magnesium 1.9 mg/dL.",
      "action_type": "ordered",
      "target": "magnesium sulfate"
    },
    {
      "text": "Monitor blood glucose closely and continue insulin therapy for hyperglycemia with glucose up to 315 mg/dL.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Obtain repeat complete blood count to monitor severe thrombocytopenia and leukocytosis (WBC up to 21.6 K/uL).",
      "action_type": "specimen_collected",
      "target": "complete blood count"
    },
    {
      "text": "Perform daily assessment of sedation and delirium with CAM-ICU and Richmond-RAS, given positive CAM-ICU and fluctuating sedation.",
      "action_type": "assessment_performed",
      "target": "delirium and sedation assessment"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with lung-protective settings and monitor ventilator parameters.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue phenylephrine infusion for hemodynamic support and monitor blood pressure.",
      "action_type": "therapy_continued",
      "target": "phenylephrine infusion"
    },
    {
      "text": "Monitor serum potassium given hyperkalemia and ongoing potassium chloride therapy.",
      "action_type": "monitored",
      "target": "serum potassium"
    },
    {
      "text": "Monitor hemoglobin and hematocrit for anemia.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Monitor coagulation parameters (PT, INR, PTT, fibrinogen).",
      "action_type": "monitored",
      "target": "coagulation panel"
    },
    {
      "text": "Monitor lactate for resolution of elevated levels.",
      "action_type": "monitored",
      "target": "lactate"
    },
    {
      "text": "Monitor blood glucose given insulin infusion and glycemic variability.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Continue insulin infusion for glycemic control.",
      "action_type": "therapy_continued",
      "target": "insulin infusion"
    },
    {
      "text": "Monitor temporary pacemaker function and settings.",
      "action_type": "monitored",
      "target": "temporary pacemaker"
    },
    {
      "text": "Perform daily assessment of sedation and neurological status.",
      "action_type": "assessment_performed",
      "target": "sedation and neurological status"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation with lung-protective settings (CMV/ASSIST/AutoFlow, PEEP 5, tidal volume ~550 mL), monitoring airway pressures and minute volume.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Wean FiO2 from 40% as tolerated while maintaining SpO2 >92%, reassessing arterial blood gases.",
      "action_type": "ordered",
      "target": "supplemental oxygen / FiO2"
    },
    {
      "text": "Transfuse packed red blood cells for severe anemia (hemoglobin 6.8–8.9 g/dL) given consent is documented.",
      "action_type": "ordered",
      "target": "packed red blood cells"
    },
    {
      "text": "Monitor hemoglobin/hematocrit serially to assess response to transfusion and ongoing blood loss.",
      "action_type": "monitored",
      "target": "hemoglobin and hematocrit"
    },
    {
      "text": "Monitor arterial blood pressure closely and maintain mean arterial pressure ≥65 mmHg, adjusting vasopressor (phenylephrine) support as needed.",
      "action_type": "monitored",
      "target": "arterial blood pressure"
    },
    {
      "text": "Continue temporary pacemaker with backup pacing (rate 52 bpm) and monitor rhythm and capture thresholds.",
      "action_type": "therapy_continued",
      "target": "temporary pacemaker"
    },
    {
      "text": "Monitor lactate trend (1.3–3.1 mmol/L) to assess tissue perfusion and resuscitation adequacy.",
      "action_type": "monitored",
      "target": "lactate"
    },
    {
      "text": "Check and replete electrolytes (ionized calcium 1.07–1.18 mmol/L, magnesium 2.6 mg/dL, potassium 3.8–4.3 mEq/L) as indicated.",
      "action_type": "monitored",
      "target": "serum electrolytes"
    },
    {
      "text": "Perform daily sedation interruption and delirium screening (CAM-ICU) while on propofol infusion.",
      "action_type": "assessment_performed",
      "target": "sedation and delirium"
    },
    {
      "text": "Provide VTE prophylaxis and continue aspiration precautions with head-of-bed elevation in the intubated patient.",
      "action_type": "ordered",
      "target": "VTE prophylaxis and aspiration precautions"
    }
  ]
}

{
  "claims": [
    {
      "text": "Maintain targeted temperature management at 35°C using the Arctic Sun device, with ongoing shivering assessment.",
      "action_type": "therapy_continued",
      "target": "Arctic Sun targeted temperature management"
    },
    {
      "text": "Continue mechanical ventilation in APV (CMV) mode with set tidal volume 450 mL, PEEP 5 cmH2O, FiO2 50%, and respiratory rate 15/min.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Continue propofol and fentanyl infusions to maintain deep sedation (goal RASS -5) during targeted temperature management.",
      "action_type": "therapy_continued",
      "target": "sedation with propofol and fentanyl"
    },
    {
      "text": "Continue norepinephrine infusion and monitor hemodynamics with non-invasive blood pressure and heart rate alarms.",
      "action_type": "therapy_continued",
      "target": "norepinephrine infusion and hemodynamic monitoring"
    },
    {
      "text": "Continue empiric broad-spectrum antibiotics (cefepime, vancomycin, metronidazole, ceftazidime) and monitor for infection given leukocytosis and sputum specimen.",
      "action_type": "therapy_continued",
      "target": "antimicrobial therapy"
    },
    {
      "text": "Monitor coagulation parameters (PTT, INR, platelet count) and continue heparin infusion with titration.",
      "action_type": "monitored",
      "target": "coagulation and heparin therapy"
    },
    {
      "text": "Monitor blood glucose and administer insulin or dextrose per protocol to maintain euglycemia.",
      "action_type": "monitored",
      "target": "glycemic control"
    },
    {
      "text": "Monitor and replace electrolytes (potassium, magnesium, calcium, phosphate) as indicated by laboratory results.",
      "action_type": "monitored",
      "target": "electrolyte management"
    },
    {
      "text": "Perform regular oral care, subglottal suctioning, and maintain endotracheal cuff pressure to prevent ventilator-associated pneumonia.",
      "action_type": "procedure_performed",
      "target": "ventilator-associated pneumonia prevention bundle"
    },
    {
      "text": "Reposition patient and implement pressure ulcer prevention strategies given Braden score indicating high risk.",
      "action_type": "procedure_performed",
      "target": "pressure ulcer prevention"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue invasive mechanical ventilation with lung-protective settings, targeting Richmond Agitation-Sedation Scale (RASS) goal of -1 to -2.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Monitor serum creatinine and urine output for acute kidney injury, avoiding nephrotoxins and adjusting renally cleared medications.",
      "action_type": "monitored",
      "target": "renal function"
    },
    {
      "text": "Monitor and manage electrolytes, including potassium and magnesium, with replacement as needed.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Continue antimicrobial therapy with vancomycin and piperacillin-tazobactam, monitoring for response and potential adverse effects.",
      "action_type": "therapy_continued",
      "target": "antimicrobial therapy"
    },
    {
      "text": "Monitor temperature and inflammatory markers (CRP) for evidence of infection or other inflammatory processes.",
      "action_type": "monitored",
      "target": "infection/inflammation"
    },
    {
      "text": "Perform daily sedation interruption and assess readiness for extubation using spontaneous breathing trials.",
      "action_type": "assessment_performed",
      "target": "sedation and weaning"
    },
    {
      "text": "Monitor blood pressure closely, especially given nicardipine infusion, and adjust antihypertensive therapy to maintain mean arterial pressure targets.",
      "action_type": "monitored",
      "target": "blood pressure"
    },
    {
      "text": "Monitor hemoglobin and hematocrit for anemia, and transfuse if indicated.",
      "action_type": "monitored",
      "target": "hemoglobin"
    },
    {
      "text": "Perform oral care and subglottic suctioning to prevent ventilator-associated pneumonia.",
      "action_type": "procedure_performed",
      "target": "ventilator-associated pneumonia prevention"
    },
    {
      "text": "Provide stress ulcer prophylaxis with a proton pump inhibitor or H2 blocker.",
      "action_type": "ordered",
      "target": "stress ulcer prophylaxis"
    }
  ]
}

{
  "claims": [
    {
      "text": "Continue mechanical ventilation weaning with spontaneous breathing trial assessment and monitor respiratory status.",
      "action_type": "therapy_continued",
      "target": "mechanical ventilation"
    },
    {
      "text": "Monitor hemodynamics with arterial line and pulmonary artery catheter, including cardiac output and blood pressure.",
      "action_type": "monitored",
      "target": "hemodynamic status"
    },
    {
      "text": "Monitor and manage temporary pacemaker settings and rhythm.",
      "action_type": "monitored",
      "target": "temporary pacemaker"
    },
    {
      "text": "Monitor blood glucose and continue insulin infusion per protocol.",
      "action_type": "monitored",
      "target": "blood glucose"
    },
    {
      "text": "Monitor hemoglobin and hematocrit; transfuse if clinically indicated.",
      "action_type": "monitored",
      "target": "hemoglobin/hematocrit"
    },
    {
      "text": "Monitor platelet count and coagulation parameters.",
      "action_type": "monitored",
      "target": "platelet count/coagulation"
    },
    {
      "text": "Monitor electrolytes including potassium, magnesium, and ionized calcium; replace as needed.",
      "action_type": "monitored",
      "target": "electrolytes"
    },
    {
      "text": "Continue analgesia and sedation with fentanyl, titrating to Richmond-RAS goal of 0.",
      "action_type": "therapy_continued",
      "target": "analgesia/sedation"
    },
    {
      "text": "Perform tracheostomy care and subglottal suctioning.",
      "action_type": "procedure_performed",
      "target": "tracheostomy care"
    },
    {
      "text": "Reposition and provide skin care per Braden scale, with chairfast activity as tolerated.",
      "action_type": "treatment_performed",
